import {esc,toast} from './ui.js';
import {roadGraph,walkingRoute,walkingLeg} from './routing.js';
let geoPromise;
export const campusGeometry=()=>geoPromise??=fetch('/shared/campus.geojson').then(r=>{if(!r.ok)throw Error('校园道路资料暂时无法读取');return r.json();}).catch(e=>{geoPromise=null;throw e;});
let amapPromise;
function loadAMap(config){if(window.AMap)return Promise.resolve(window.AMap);return amapPromise??=new Promise((resolve,reject)=>{window._AMapSecurityConfig={serviceHost:location.origin+config.securityProxy};const s=document.createElement('script');s.src='https://webapi.amap.com/maps?v=2.0&key='+encodeURIComponent(config.amapKey);s.onload=()=>window.AMap?resolve(window.AMap):reject(Error('地图加载失败'));s.onerror=()=>reject(Error('高德地图暂时无法连接'));document.head.append(s);setTimeout(()=>reject(Error('高德地图连接超时')),12000);});}
const trust=p=>p.trust==='certified'?'已经过认证':p.trust==='community'?'社区共创点位':'地图资料点位';
export async function campusMap(element,catalog,{onPoint,onPick,canPick=()=>true,trail=[],routeStops=[]}={}){
 if(catalog.map?.provider==='amap'&&catalog.map.amapKey&&!onPick&&!routeStops.length){try{return await amapMap(element,catalog,onPoint,trail);}catch(e){toast(e.message+'，已切换校园地图');}}
 const L=window.L,geo=await campusGeometry();if(!element.isConnected)return {destroy(){},trail(){},locate(){}};
 const map=L.map(element,{zoomControl:false,attributionControl:true,scrollWheelZoom:false,zoomSnap:1,zoomDelta:1}).setView([catalog.campus.center[1],catalog.campus.center[0]],16);
 L.control.zoom({position:'bottomright'}).addTo(map);map.attributionControl.addAttribution('<a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap</a>');
 map.createPane('campus-vector');map.getPane('campus-vector').style.zIndex=350;
 const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,minZoom:14});let loaded=0,failed=0,autoFallback=false;
 const notice=document.createElement('div');notice.className='map-status';notice.textContent='真实校园地图 · WGS84';element.append(notice);
 let detail;const stamp=geo.metadata?.fetchedAt?.slice(0,10)||'未标记';
 const setNotice=text=>{notice.textContent=text;notice.title='道路资料获取于 '+stamp+'；获取日期不是实地测绘日期。最新道路编辑：'+(geo.metadata?.latestRoadEdit?.slice(0,10)||'未标记');};
 tiles.on('tileload',()=>{loaded++;if(autoFallback&&map.hasLayer(detail)){map.removeLayer(detail);autoFallback=false;}if(map.hasLayer(tiles))setNotice('在线街道地图 · 道路资料 '+stamp);});tiles.on('tileerror',()=>{failed++;if(!loaded&&failed>=3&&detail){if(!map.hasLayer(detail)){detail.addTo(map);autoFallback=true;}setNotice('底图连接受限 · 已保存校园详图 '+stamp);}});tiles.addTo(map);
 detail=L.layerGroup();L.geoJSON(geo,{pane:'campus-vector',filter:f=>f.properties?.kind!=='campus',style:f=>{const kind=f.properties?.kind,building=kind==='building',road=f.geometry.type==='LineString';return {color:road?'#ffffff':building?'#a8b9c8':'#c0d4bc',weight:road?(kind==='footway'?3:7):1,fillColor:building?'#d9e3eb':kind==='pitch'||kind==='stadium'?'#b8d4b2':'#e8eee0',fillOpacity:building?.95:.7};},onEachFeature:(f,layer)=>{if(f.properties.name&&f.geometry.type==='Polygon')layer.bindTooltip(esc(f.properties.name),{permanent:true,direction:'center',className:'campus-building-label'});}}).addTo(detail);
 L.geoJSON(geo,{pane:'campus-vector',filter:f=>f.geometry.type==='LineString',style:f=>({color:'#b3bdc8',weight:f.properties.kind==='footway'?1:2,opacity:.7})}).addTo(detail);
 const layers=L.control.layers({'在线街道地图':tiles,'校园详图':detail},null,{position:'topright'}).addTo(map);const toggle=layers.getContainer().querySelector('.leaflet-control-layers-toggle');toggle.setAttribute('aria-label','切换地图：在线街道 / 校园详图');toggle.title='切换地图：在线街道 / 校园详图';
 map.on('baselayerchange',e=>{autoFallback=false;if(e.layer===tiles&&map.hasLayer(detail))map.removeLayer(detail);setNotice(e.layer===detail?'校园详图 · 资料 '+stamp:'在线街道地图 · 道路资料 '+stamp);});
 setNotice('正在连接在线底图 · 可切换校园详图');
 const boundary=L.polygon(catalog.campus.boundary.map(p=>[p[1],p[0]]),{color:'#668a9c',weight:1.5,dashArray:'5 7',fill:false}).addTo(map);map.fitBounds(boundary.getBounds(),{padding:[28,28],animate:false});map.setMaxBounds(boundary.getBounds().pad(.65));
 const markers=new Map();for(const p of catalog.points){const number=routeStops.findIndex(s=>s.id===p.id)+1;const marker=L.marker([p.lat,p.lng],{title:p.name,icon:L.divIcon({className:'campus-pin '+(number?'route-pin ':p.trust==='community'?'community':''),html:number?`<span><b>${number}</b></span>`:'<span>●</span>',iconSize:[30,36],iconAnchor:[15,33]})}).addTo(map);marker.getElement()?.setAttribute('aria-label',(number?`第 ${number} 站：`:'地图点位：')+p.name);marker.bindTooltip(`${number?'第 '+number+' 站 · ':''}${esc(p.name)}<br><small>${trust(p)}</small>`,{direction:'top',offset:[0,-24]});marker.on('click',()=>{map.panTo(marker.getLatLng());onPoint?.(p.id);});markers.set(p.id,marker);}
 let pickMarker; if(onPick)map.on('click',e=>{if(!canPick())return;const chosen={lng:e.latlng.lng,lat:e.latlng.lat};if(onPick(chosen)===false)return;if(!pickMarker)pickMarker=L.marker(e.latlng,{icon:L.divIcon({className:'campus-pin selected',html:'<span>＋</span>',iconSize:[30,36],iconAnchor:[15,33]})}).addTo(map);else pickMarker.setLatLng(e.latlng);});
 const path=L.polyline(trail.map(p=>[p.lat,p.lng]),{color:'#ec6a3a',weight:4}).addTo(map);let dot,circle;
 const graph=roadGraph(geo),reference=walkingRoute(graph,routeStops),routeLayer=L.layerGroup().addTo(map),navLayer=L.layerGroup().addTo(map);
 const drawLeg=(layer,leg,color)=>{if(!leg.available)return;L.polyline(leg.path.map(c=>[c[1],c[0]]),{color:'#fff',weight:9,opacity:.95}).addTo(layer);L.polyline(leg.path.map(c=>[c[1],c[0]]),{color,weight:5,opacity:.85}).addTo(layer);for(const cs of leg.connectors)L.polyline(cs.map(c=>[c[1],c[0]]),{color,weight:3,dashArray:'4 7',opacity:.6}).addTo(layer);};
 reference.legs.forEach(leg=>drawLeg(routeLayer,leg,'#5276c7'));
 const overview=(animate=true)=>{if(routeStops.length>1)map.fitBounds(L.latLngBounds(routeStops.map(p=>[p.lat,p.lng])),{padding:[45,45],maxZoom:18,animate});else map.fitBounds(boundary.getBounds(),{padding:[28,28],animate});};if(routeStops.length)overview(false);
 let plannedBounds=null;const resize=new ResizeObserver(()=>{map.invalidateSize();if(plannedBounds)map.fitBounds(plannedBounds,{padding:[48,48],maxZoom:18,animate:false});else if(routeStops.length)overview(false);});resize.observe(element);
 return {reference,overview,graph,metadata:geo.metadata,plan(start,target,{fit=true}={}){navLayer.clearLayers();const leg=walkingLeg(graph,start,target);drawLeg(navLayer,leg,'#2878e4');if(leg.available){for(const [p,label] of [[start,'起'],[target,'终']])L.marker([p.lat,p.lng],{icon:L.divIcon({className:'journey-marker '+(label==='起'?'start':'end'),html:'<span>'+label+'</span>',iconSize:[30,30],iconAnchor:[15,15]})}).addTo(navLayer);if(fit){plannedBounds=L.latLngBounds([start,target,...leg.path.map(p=>({lat:p[1],lng:p[0]}))]);map.fitBounds(plannedBounds,{padding:[48,48],maxZoom:18});}}return leg;},navigation(p,target){if(!element.isConnected)return null;navLayer.clearLayers();if(!p||!target)return null;const leg=walkingLeg(graph,p,target);drawLeg(navLayer,leg,'#31846c');return leg;},focus(id){const m=markers.get(id);if(m){map.setView(m.getLatLng(),18);m.openTooltip();}},trail(points){path.setLatLngs(points.map(p=>[p.lat,p.lng]));},locate(p,{follow=true}={}){if(!element.isConnected)return;if(!dot){dot=L.circleMarker([p.lat,p.lng],{radius:7,color:'#fff',weight:3,fillColor:'#2879ff',fillOpacity:1}).addTo(map);circle=L.circle([p.lat,p.lng],{radius:p.accuracy,color:'#2879ff',weight:1,fillOpacity:.08}).addTo(map);}else{dot.setLatLng([p.lat,p.lng]);circle.setLatLng([p.lat,p.lng]).setRadius(p.accuracy);}if(follow&&inCampus(p,catalog.campus))map.panTo([p.lat,p.lng]);},destroy(){resize.disconnect();map.remove();}};
}
async function amapMap(element,catalog,onPoint,trail){const A=await loadAMap(catalog.map);const coords=[catalog.campus.center,...catalog.points.map(p=>[p.lng,p.lat]),...catalog.campus.boundary];const converted=await new Promise((resolve,reject)=>A.convertFrom(coords,'gps',(status,result)=>status==='complete'?resolve(result.locations):reject(Error('地图坐标转换失败'))));if(!element.isConnected)return {destroy(){}};const map=new A.Map(element,{center:converted[0],zoom:16,viewMode:'2D'});const markers=[];catalog.points.forEach((p,i)=>{const m=new A.Marker({position:converted[i+1],title:p.name,content:'<div class="amap-campus-pin">●</div>'});map.add(m);m.on('click',()=>onPoint?.(p.id));markers.push(m);});const polygon=new A.Polygon({path:converted.slice(catalog.points.length+1),strokeColor:'#ed6a37',strokeWeight:2,fillOpacity:.06});map.add(polygon);map.setFitView([polygon]);let polyline,dot;function convert(points,cb){if(!points.length)return;A.convertFrom(points.map(p=>[p.lng,p.lat]),'gps',(s,r)=>{if(s==='complete')cb(r.locations);});}function update(points){convert(points,c=>{if(!polyline){polyline=new A.Polyline({path:c,strokeColor:'#ed6a37',strokeWeight:4});map.add(polyline);}else polyline.setPath(c);});}update(trail);return{focus(id){const i=catalog.points.findIndex(p=>p.id===id);if(i>=0)map.setZoomAndCenter(18,converted[i+1]);},trail:update,locate(p){convert([p],c=>{if(!dot){dot=new A.Marker({position:c[0],content:'<div class="location-dot"></div>'});map.add(dot);}else dot.setPosition(c[0]);map.panTo(c[0]);});},destroy(){map.destroy();}};}
export function inCampus(p,campus){let inside=false;const b=campus.boundary;for(let i=0,j=b.length-1;i<b.length;j=i++){if((b[i][1]>p.lat)!==(b[j][1]>p.lat)&&p.lng<(b[j][0]-b[i][0])*(p.lat-b[i][1])/(b[j][1]-b[i][1])+b[i][0])inside=!inside;}return inside;}
